<template><div class="pro-page page-animate"><div class="wrap"><section class="member-hero pro-panel"><div><span class="eyebrow">Member workspace</span><h1>Welcome back, {{ auth.user?.name || 'Member' }}</h1><p>Manage your Premium access, saved picks and football activity.</p></div><RouterLink to="/subscription" class="btn">Manage Premium</RouterLink></section><section class="member-grid"><div class="pro-panel"><span class="eyebrow">Premium</span><h2>Your membership</h2><p>View subscription options and unlock Premium predictions.</p><RouterLink to="/subscription" class="ghost">View subscription →</RouterLink></div><div class="pro-panel"><span class="eyebrow">Saved picks</span><h2>{{ openPicks }} open picks</h2><p>{{ wonPicks }} winning results tracked in your account.</p><RouterLink to="/history" class="ghost">Prediction history →</RouterLink></div><div class="pro-panel"><span class="eyebrow">Following</span><h2>Discover tipsters</h2><p>Browse tipster profiles and published records.</p><RouterLink to="/tipsters" class="ghost">Browse tipsters →</RouterLink></div></section><section class="pro-panel"><div class="pro-section-head"><div><span class="eyebrow">My activity</span><h2>Saved and tracked picks</h2></div><RouterLink to="/picks">Find predictions →</RouterLink></div><div v-if="picks.length" class="my-pick-list"><div v-for="x in picks" :key="x._id" class="my-pick-row"><span :class="['result-badge',x.status]">{{x.status}}</span><div><b>{{x.predictionId?.fixture||'Football match'}}</b><small>{{x.predictionId?.prediction}}</small></div><b>{{formatOdds(x.predictionId?.odds)}}</b></div></div><EmptyState v-else title="No saved picks yet" message="Save predictions to track them here."><template #action><RouterLink to="/picks" class="btn">Explore predictions</RouterLink></template></EmptyState></section></div></div></template><script setup lang="ts">import{computed,onMounted,ref}from'vue';import{RouterLink}from'vue-router';import{useAuth}from'../stores/auth';import{api}from'../services/api';import{formatOdds}from'../utils/formatters';import EmptyState from'../components/EmptyState.vue';const auth=useAuth();const picks=ref<any[]>([]);const openPicks=computed(()=>picks.value.filter(x=>x.status==='open').length);const wonPicks=computed(()=>picks.value.filter(x=>x.status==='won').length);onMounted(async()=>{try{picks.value=(await api.get('/me/picks')).data||[]}catch{}})</script><style scoped>.member-hero{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.member-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:24px}.member-grid .pro-panel{min-height:190px}.my-pick-row{display:grid;grid-template-columns:110px 1fr auto;gap:16px;padding:15px 0;border-top:1px solid var(--border)}small{display:block;color:var(--muted);margin-top:4px}@media(max-width:760px){.member-grid{grid-template-columns:1fr}.member-hero{align-items:flex-start;gap:16px;flex-direction:column}}</style>